import UIKit

/// Payment brand marks, the same ones the Vezmo web checkout and dashboard show (card tiles in each network's own
/// colour; the official UPI and Pix marks), as 3x PNGs so the package ships no image asset. They sit on a white tile
/// in both themes: these are other companies' marks and are not recoloured for dark mode.
enum Mark: String, CaseIterable {
  case visa, mastercard, amex, discover, upi, pix

  /// The mark's size in points.
  var size: CGSize {
    switch self {
    case .visa: return CGSize(width: 18, height: 16)
    case .mastercard: return CGSize(width: 18, height: 16)
    case .amex: return CGSize(width: 18, height: 16)
    case .discover: return CGSize(width: 18, height: 16)
    case .upi: return CGSize(width: 24, height: 8.33)
    case .pix: return CGSize(width: 24, height: 8.67)
    }
  }

  var image: UIImage { Mark.images[self]! }

  private static let images: [Mark: UIImage] = Dictionary(uniqueKeysWithValues: allCases.map { ($0, png($0.base64)) })

  private var base64: String {
    switch self {
    case .visa: return ""
    case .mastercard: return ""
    case .amex: return ""
    case .discover: return ""
    case .upi: return ""
    case .pix: return ""
    }
  }

  /// The card network's mark for a brand as the server names it (`visa`, `American Express`, `master_card`…).
  static func forBrand(_ brand: String?) -> Mark? {
    let key = (brand ?? "").lowercased().filter { !" _-".contains($0) && !$0.isWhitespace }
    switch key {
    case "visa": return .visa
    case "mastercard", "master": return .mastercard
    case "amex", "americanexpress": return .amex
    case "discover": return .discover
    default: return nil
    }
  }
}

/// The Vezmo logo (the same artwork as the hosted checkout's "Powered by"), at 3x of 14pt tall. Dark themes tint it
/// white, as the web does.
enum VezmoLogo {
  static let size = CGSize(width: 50.7, height: 14)
  static let image = png("")
}

private func png(_ base64: String) -> UIImage {
  UIImage(data: Data(base64Encoded: base64)!, scale: 3)!
}
